def apply_discount(price_cents, percent):
    """Price after a percentage discount, in whole cents. Half a cent rounds up."""
    return int(price_cents * (100 - percent) / 100 + 0.5)

def parse_csv_line(line):
    """Split one CSV line into fields. Fields in double quotes may contain commas."""
    fields = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            fields.append(current_field.strip('"'))
            current_field = ""
        else:
            current_field += char

    fields.append(current_field.strip('"'))
    return fields

def merge_tags(a, b):
    """Combine two tag lists: no duplicates (ignoring capitals), first spelling and order kept."""
    result = list(a)
    for tag in b:
        if not any(tag.lower() == existing.lower() for existing in result):
            result.append(tag)
    return result

